    q = deque([root])
    while q:
        depth += 1
        for _ in range(len(q)):
            node = q.popleft()
            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)

    res = [["" for _ in range((1 << depth) - 1)] for _ in range(depth)]

    # Fill in matrix
